const body = $input.first().json.body || {};
const out = [];
const seen = new Set();
for (const entry of body.entry || []) {
  for (const ch of entry.changes || []) {
    if (ch.field !== 'comments') continue;
    const v = ch.value || {};
    const from = v.from || {};
    if (!v.id || !from.id || seen.has(v.id)) continue;
    // Never react to our own comments (our public replies come back as webhooks too)
    if (String(from.id) === String(entry.id)) continue;
    seen.add(v.id);
    out.push({ json: {
      comment_id: String(v.id),
      text: String(v.text || ''),
      user_id: String(from.id),
      username: String(from.username || ''),
      media_id: String((v.media || {}).id || ''),
      media_type: String((v.media || {}).media_product_type || ''),
      account_id: String(entry.id)
    } });
  }
}
return out;

// Cheap first pass: keep only comments that contain at least one active keyword.
const s = $('⚙️ Load Settings').first().json;
const reels = $('🎬 Load Active Reels').all().map(i => i.json).filter(r => r && r.active);
const norm = t => ' ' + String(t || '').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu, ' ').trim() + ' ';
const matches = (r, text) => String(r.keyword || '').split(',').map(k => k.trim()).filter(Boolean)
  .some(k => k === '*' || (norm(k).trim() && text.includes(norm(k))));
const me = String(s.ig_username || '').toLowerCase().replace(/^@/, '');

const out = [];
for (const it of $('📥 Extract Comments').all()) {
  const c = it.json;
  if (me && c.username.toLowerCase() === me) continue;
  if (s.ig_user_id && String(c.user_id) === String(s.ig_user_id)) continue;
  const text = norm(c.text);
  if (reels.some(r => matches(r, text))) out.push({ json: c });
}
return out;

const s = $('⚙️ Load Settings').first().json;
// Newest row first, so re-adding a reel overrides its older row
const reels = $('🎬 Load Active Reels').all().map(i => i.json).filter(r => r && r.active)
  .sort((a, b) => Number(b.id) - Number(a.id));
const pre = $('🔎 Keyword Prefilter').all();
const info = $input.all();

const norm = t => ' ' + String(t || '').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu, ' ').trim() + ' ';
const codeOf = u => (String(u || '').match(/\/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/) || [])[1] || '';
const pick = txt => { const v = String(txt || '').split('||').map(x => x.trim()).filter(Boolean); return v.length ? v[Math.floor(Math.random() * v.length)] : ''; };
const isAll = r => ['ALL', '*'].includes(String(r.reel_url || '').trim().toUpperCase());
const minD = Math.max(1, Number(s.min_delay_sec) || 4);
const maxD = Math.max(minD, Number(s.max_delay_sec) || 15);

const out = [];
pre.forEach((p, i) => {
  const c = p.json;
  const m = (info[i] && info[i].json) || {};
  const shortcode = m.shortcode || codeOf(m.permalink);
  const text = norm(c.text);
  const kwHit = r => String(r.keyword || '').split(',').map(k => k.trim()).filter(Boolean)
    .find(k => k === '*' || (norm(k).trim() && text.includes(norm(k))));

  const sameReel = r => (r.media_id && String(r.media_id) === c.media_id) || (shortcode && codeOf(r.reel_url) === shortcode);
  const specific = reels.filter(r => sameReel(r) && kwHit(r));
  const general = reels.filter(r => isAll(r) && kwHit(r));
  const r = specific[0] || general[0];
  if (!r) return;

  const fill = t => t.replace(/\{username\}/g, c.username).replace(/\{link\}/g, r.link || '');
  const dm = fill(pick(r.dm_message) || 'Hey @{username} 👋 Ye raha aapka link: {link}');
  out.push({ json: {
    ...c,
    shortcode,
    reel_row_id: r.id,
    keyword: kwHit(r),
    dm_text: dm.slice(0, 1000),
    public_reply_text: fill(pick(r.public_reply)).slice(0, 300),
    delay_sec: minD + Math.floor(Math.random() * (maxD - minD + 1))
  } });
});
return out;

const c = $('🔁 One Comment at a Time').first().json;
const sent = $input.all().filter(i => i.json && i.json.id).length;
const cap = Number($('⚙️ Load Settings').first().json.max_dms_per_hour) || 150;
return [{ json: { ...c, sent_last_hour: sent, over_cap: sent >= cap } }];

// Claim pattern: whoever wrote the oldest claimed/sent row for this person+reel wins.
// Stops double DMs even when someone comments 6 times in 2 seconds.
const c = $('🚦 Hourly Cap Check').first().json;
const myId = $('🔒 Claim in Log').first().json.id;
const ids = $input.all().map(i => i.json)
  .filter(r => r && r.id && ['claimed', 'sent'].includes(r.status))
  .map(r => Number(r.id));
const isFirst = ids.length ? Math.min(...ids) === Number(myId) : true;
return [{ json: { ...c, log_id: myId, is_first: isFirst } }];

// Which media ids to check for new comments
const reels = $('🎬 Poll Active Reels').all().map(i => i.json).filter(r => r && r.active);
const media = (($input.first() || {}).json || {}).data || [];
const codeOf = u => (String(u || '').match(/\/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/) || [])[1] || '';
const isAll = r => ['ALL', '*'].includes(String(r.reel_url || '').trim().toUpperCase());
const ids = new Set();
for (const r of reels) {
  if (isAll(r)) { media.slice(0, 10).forEach(m => ids.add(String(m.id))); continue; }
  if (r.media_id) { ids.add(String(r.media_id)); continue; }
  const m = media.find(x => x.shortcode && x.shortcode === codeOf(r.reel_url));
  if (m) ids.add(String(m.id));
}
return [...ids].map(media_id => ({ json: { media_id } }));

// Turn fresh, unhandled comments into the same body shape Meta's webhook sends
const s = $('⚙️ Poll Settings').first().json;
const me = String(s.ig_user_id || '');
const seen = new Set($('📒 Recent Log').all().map(i => i.json && String(i.json.comment_id || '')).filter(Boolean));
const cutoff = Date.now() - 15 * 60 * 1000;
const mediaIds = $('🧮 Reels to Poll').all().map(i => i.json.media_id);
const changes = [];
$('💭 Fetch Comments').all().forEach((it, idx) => {
  const media_id = mediaIds[idx];
  for (const c of (it.json && it.json.data) || []) {
    const from = c.from || {};
    if (!c.id || !from.id || String(from.id) === me) continue;
    if (seen.has(String(c.id))) continue;
    if (new Date(c.timestamp).getTime() < cutoff) continue;
    seen.add(String(c.id));
    changes.push({ field: 'comments', value: { id: String(c.id), text: c.text || '', from: { id: String(from.id), username: from.username || '' }, media: { id: String(media_id), media_product_type: 'REELS' } } });
  }
});
if (!changes.length) return [];
return [{ json: { body: { object: 'instagram', entry: [{ id: me, time: Math.floor(Date.now() / 1000), changes }] }, source: 'poll' } }];
